function getTriggerInput() {
  try { return $('Receive workflow call').first().json; } catch (error) {}
  try { return $('Receive request').first().json; } catch (error) {}
  return $json;
}
const inputRoot = getTriggerInput();
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || 'req_' + executionId;
const aiText = ai.output || ai.text || ai.response || ai.message || '';

function safeJson(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value || '').trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  const firstBrace = candidate.indexOf('{');
  const lastBrace = candidate.lastIndexOf('}');
  if (firstBrace < 0 || lastBrace <= firstBrace) return null;
  try { return JSON.parse(candidate.slice(firstBrace, lastBrace + 1)); } catch { return null; }
}

const parsed = safeJson(aiText) || {};
const parsedOutput = parsed.output && typeof parsed.output === 'object' ? parsed.output : parsed;
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'knowledge_fabric_agent',
  status: 'completed',
  approval: { required: false },
  output: {
    summary: parsedOutput.summary || parsedOutput.answer || aiText || 'Knowledge Fabric staged source context as pending OKF material.',
    created_candidates: parsedOutput.created_candidates || input.input?.created_candidates || [],
    review_state: parsedOutput.review_state || 'pending-review',
    graph_curator_trigger: parsedOutput.graph_curator_trigger || 'candidate_edges_pending_review',
    vector_refresh: parsedOutput.vector_refresh || 'deferred_until_approval',
    concept_path: parsedOutput.concept_path || '',
    evidence_path: parsedOutput.evidence_path || '',
    contract_stage: 'ai_agent_normalized',
    ai_agent: { integrated: true, node: 'Knowledge Fabric AI Agent' }
  },
  trace: { stored: true, trace_id: 'n8n_exec_' + executionId, used_agents: ['knowledge_fabric_agent_ai_agent', 'graph_curator_boundary', 'vector_refresh_boundary'], target_agent: 'knowledge_fabric_agent', route_decision: input.context?.route_decision?.decision || 'ingest_or_stage_knowledge', handoff_status: 'handoff_completed', ai_agent_integrated: true }
};
return [{ json: response }];

